import{_ as t,o as a,c as s,a3 as r}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Project vision","description":"Build knowledge that remains useful when sources disagree, models change, or hardware disappears.","frontmatter":{"title":"Project vision","description":"Build knowledge that remains useful when sources disagree, models change, or hardware disappears."},"headers":[],"relativePath":"guide/vision.md","filePath":"guide/vision.md","lastUpdated":1794433168000}'),i={name:"guide/vision.md"};function o(n,e,d,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="knowledge-you-can-stand-behind" tabindex="-1">Knowledge you can stand behind <a class="header-anchor" href="#knowledge-you-can-stand-behind" aria-label="Permalink to &quot;Knowledge you can stand behind&quot;">​</a></h1><p><strong>Turn raw sources into knowledge you can inspect, correct, move and publish.</strong></p><p>Ordo Knowledge Lab is a local-first research workspace. AI helps process material and propose connections. People and explicit policies decide what enters the published library. The library retains the evidence behind those decisions.</p><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>An answer alone is not a maintained body of knowledge. We need to know which source supported a statement, whether several reports are independent, whether two names refer to one entity, and what changed when new evidence arrived.</p><p>Our design treats those questions as records and workflows—not as instructions we hope a chatbot follows.</p><h2 id="the-promise" tabindex="-1">The promise <a class="header-anchor" href="#the-promise" aria-label="Permalink to &quot;The promise&quot;">​</a></h2><p><strong>Every accepted claim has a trail.</strong> Keep source locations, extraction receipts, review decisions and revision history. A reader can inspect the evidence rather than trust fluent wording.</p><p><strong>Uncertainty stays visible.</strong> Preserve conflicting testimony, unresolved identities and scoring limitations. A well-extracted statement is not automatically a true statement.</p><p><strong>Knowledge outlives its tools.</strong> A library created with a Mac worker must remain readable on Linux. Missing models disable particular operations, not access to existing evidence.</p><p><strong>Automation has boundaries.</strong> Rust owns state and publication. Workers propose results through versioned contracts; model text cannot grant permissions or merge identities.</p><h2 id="who-it-serves" tabindex="-1">Who it serves <a class="header-anchor" href="#who-it-serves" aria-label="Permalink to &quot;Who it serves&quot;">​</a></h2><p>Researchers build and correct a library. Instructors demonstrate how evidence moves through a real system. Students trace requirements into code, reproduce failures, and explain what tests prove. Readers explore an approved snapshot through search and streaming chat.</p><p>UFO reports are the first teaching domain. The engine should support other evidence-heavy collections without embedding UFO-specific assumptions in its core.</p><h2 id="the-first-meaningful-success" tabindex="-1">The first meaningful success <a class="header-anchor" href="#the-first-meaningful-success" aria-label="Permalink to &quot;The first meaningful success&quot;">​</a></h2><p>Import conflicting synthetic reports. Resolve one alias without merging two people who share a name. Publish a reviewed revision. Stream an answer whose citations open the exact evidence. Move the library to a machine with a processing capability missing.</p><p>That is the first complete demonstration. It is not yet implemented. <a href="./walkthrough">Follow the walkthrough</a>.</p><h2 id="deliberate-limits" tabindex="-1">Deliberate limits <a class="header-anchor" href="#deliberate-limits" aria-label="Permalink to &quot;Deliberate limits&quot;">​</a></h2><p>We are not building an autonomous truth engine, universal scraper or distributed platform first. Version one does not require simultaneous editing of one library on multiple machines, unrestricted public uploads, or advanced video processing.</p><p>Reuse useful Ordo code, repair its known gaps, and prove a small end-to-end workflow before adding infrastructure. <a href="./../build/">See the build strategy</a>.</p>',20)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
